user_prompt='做一个《小蝌蚪找妈妈》的水墨动画，添加合适的音乐，请务必做到引人入胜，如果需要用到旁白或对话，用TTS合成，字幕用中英双语'
pond_prompt="""Create a gorgeous cinematic wide 16:9 traditional Chinese ink wash painting background for a children's animation about tadpoles finding their mother. Empty pond setting ONLY, no animals, no tadpoles, no frogs, no text. Warm ivory rice paper texture, expressive sumi-e ink bleeding and delicate moss-green watercolor lotus leaves, a few pale blush lotus blossoms, graceful reeds at far left and far right, misty distant willow shoreline upper fifth. Composition: lots of airy pale open water in center and lower two thirds for animated characters. Rich authentic handmade brush texture, poetic tranquil spring morning, restrained elegant fine art, soft layered gray ink reflections, generous negative space. Full bleed landscape frame, no borders."""
character_prompt="""Asset type: transparent sprite sheet for a traditional Chinese ink wash children's animation. Paint FOUR separate animals arranged in a precise 2 columns by 2 rows grid, each entirely contained within its quadrant with generous empty margins and no overlap. TOP LEFT: mother duck facing right, side view, elegant ivory and pale ochre wash with fluid black brush wing and orange beak. TOP RIGHT: golden orange carp facing right, side view, flowing translucent fins and a large kind eye. BOTTOM LEFT: friendly turtle facing right, side view, moss green shell with expressive ink hexagons and four visible short legs. BOTTOM RIGHT: smiling mother frog, front view, moss green ink wash, two large kind eyes, pale belly, four legs in crouched pose. The characters should be expressive and charming, unmistakably HAND PAINTED INK WASH with dry brush texture, diluted watercolor blooms, irregular brush edges, subtle paper-like grain inside colored areas, black ink accents. Fine Chinese picture book art with white spaces left inside forms. NO smooth flat vector shapes, NO glossy 3d, NO text, NO pond, NO leaves, NO ground, NO cast shadow. Transparent background. All characters similar visual size. Four individual animals only."""
def embedded(name):
 return 'data:image/jpeg;base64,'+base64.b64encode((assets/name).read_bytes()).decode('ascii')
def time(t):return f'{int(t)//60:02}:{t%60:05.2f}'
chapters=[('初醒','A new world','Establish spring and introduce the six tadpoles.'),('一问','Mother Duck','Introduce the question and the clue: two big eyes.'),('再问','The golden carp','A mistaken identification adds the clue: four legs.'),('线索','Four little legs','The turtle supplies the final clue: a green coat.'),('风雨','Stay together','Darken the pond, add rain, cluster the tadpoles, and lower the score.'),('回声','A familiar voice','Reveal the frog beneath a lotus leaf and bring the tadpoles closer.'),('团圆','Home','Show little legs, return to warmth, and finish with a message about love.')]
bounds=[0]+[min(x['start'] for x in timeline if x['scene']==s)-1 for s in range(1,7)]
cards=''.join(f'<article class="scene"><img src="{embedded(f"check_{s}.jpg")}" alt="Scene {s+1}: {esc(en)}"><div><small>{s+1:02} · {time(bounds[s])}</small><h3>{zh} / {en}</h3><p>{desc}</p></div></article>' for s,(zh,en,desc) in enumerate(chapters))
roles=['Narrator','Narrator','Narrator','Tadpoles','Adult animal','Narrator','Adult animal','Tadpoles','Adult animal','Narrator','Tadpoles','Narrator','Narrator','Tadpoles','Mother frog','Narrator','Narrator']
rows=''.join(f'<tr><td>{i+1:02}</td><td class="nowrap">{time(x["start"])}–{time(x["end"])}</td><td>{roles[i]}</td><td lang="zh-CN">{esc(x["zh"])}</td><td>{esc(x["en"])}</td></tr>' for i,x in enumerate(timeline))
file_rows=[('tadpoles_find_their_mother_ink_animation.mp4','Root','Final H.264 / AAC film; 16,506,791 bytes.'),('watch.html','Root','Local player; video link in root, poster and subtitle links under output/tadpoles.'),('production_notes.md','Root','Chinese production notes.'),('implementation_report.html','Root','This self-contained report; inline CSS and embedded scene images.'),('subtitles.zh-en.srt','output/tadpoles','17 bilingual subtitle cues.'),('soundtrack.wav','output/tadpoles','16-bit PCM stereo master: speech, music and rain together.'),('pond.png / characters.png','output/tadpoles','Generated pond background and transparent character sheet.'),('voice_00.mp3 … voice_16.mp3','output/tadpoles','Cached Chinese TTS clips.'),('timeline.json / validation.json','output/tadpoles','Dialogue timings and recorded validation results.'),('make_film.py','output/tadpoles','Animation, TTS, soundtrack and MP4 production source.'),('check_frames.py / validate_film.py','output/tadpoles','Scene inspection and full-video decoding checks.')]
files=''.join(f'<tr><td><code>{esc(n)}</code></td><td><code>{folder}</code></td><td>{desc}</td></tr>' for n,folder,desc in file_rows)
